<script>
(()=>{const find=document.getElementById('promo-find');if(!find)return;async function search(){const q=document.getElementById('promo-search').value.trim(),msg=document.getElementById('promo-message'),out=document.getElementById('promo-results');out.replaceChildren();if(q.length<2){msg.textContent='กรอกอย่างน้อย 2 ตัวอักษร';return}msg.textContent='กำลังค้นหา…';try{const url=new URL(@json(route('ns.scheduled-prices.lookup')),location.origin);url.searchParams.set('q',q);const res=await fetch(url,{headers:{Accept:'application/json'}});if(!res.ok)throw Error();const rows=await res.json();msg.textContent=rows.length?'เลือกสินค้าและหน่วยขาย':'ไม่พบสินค้า';rows.forEach(row=>{const b=document.createElement('button');b.type='button';b.textContent=row.label;b.onclick=()=>{const select=document.getElementById('promo-unit');select.replaceChildren(new Option(row.label,row.id,true,true));out.replaceChildren();msg.textContent='เลือกแล้ว: '+row.label};out.append(b)})}catch{msg.textContent='ค้นหาไม่สำเร็จ กรุณาลองใหม่'}}find.onclick=search;document.getElementById('promo-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search()}}})();
</script>
